 40→export function SessionDetail({ session, authorUsername, activated }: SessionDetailProps) {
 41→  const [expanded, setExpanded] = useState(true);
 42→
 43→  if (activated && !expanded) {
 44→    setExpanded(true);
 45→  }
 46→
 47→  const [drawerToolCalls, setDrawerToolCalls] = useState<ToolCall[] | null>(null);
 48→
