 1→import type { TranscriptMessage } from "../../types";
 2→
 3→/**
 4→ * Result of parsing a transcript, including metadata about parse quality.
 5→ */
 6→export interface TranscriptParseResult {
 7→  messages: TranscriptMessage[];
 8→  /** True when the parser is a best-effort fallback, not a native parser for this agent */
 9→  isFallback: boolean;
10→  /** Warning message when parsing may be incomplete */
11→  warning?: string;
12→}
13→
14→/**
15→ * Interface that every agent transcript parser must implement.
16→ */
17→export interface TranscriptParser {
18→  /** Human-readable name for this parser */
19→  readonly name: string;
20→  /** Parse raw JSONL content into transcript messages */
21→  parse(jsonlContent: string): TranscriptParseResult;
22→}
23→

 1→import { ClaudeCodeParser } from "./claude-code-parser";
 2→import type { TranscriptParser, TranscriptParseResult } from "./types";
 3→
 4→/**
 5→ * Fallback parser for unknown agents.
 6→ * Delegates to ClaudeCodeParser for best-effort parsing (the Anthropic API
 7→ * message format is common across agents using the checkpoint protocol)
 8→ * but marks the result as a fallback so the frontend can show a warning.
 9→ */
10→export class FallbackParser implements TranscriptParser {
11→  readonly name = "Fallback";
12→  private delegate = new ClaudeCodeParser();
13→
14→  parse(jsonlContent: string): TranscriptParseResult {
15→    const result = this.delegate.parse(jsonlContent);
16→    return {
17→      messages: result.messages,
18→      isFallback: true,
19→      warning:
20→        "Full transcript parsing is not yet available for this agent. Some messages or tool calls may not display correctly.",
21→    };
22→  }
23→}
