 1→// Shared transcript utilities used by webhook consumers, search index queue, and summary queue
 2→
 3→import { fetchFileAtCommit } from "./github";
 4→import { CHECKPOINT_BRANCH, checkpointFolderPath } from "./constants";
 5→import { stripTranscript } from "./strip-transcript";
 6→import type { Db } from "./db/db-types";
 7→
 8→export const TRANSCRIPT_CONCURRENCY = 10;
 9→
10→// Fetch transcript from GitHub, strip it, and return the stripped JSONL
11→// Returns a per-session map: { "0": "stripped jsonl...", "1": "..." }
12→export async function fetchAndStripTranscript(
13→  repoFullName: string,
14→  checkpointId: string,
15→  sessionCount: number,
16→  token: string,
17→): Promise<Record<string, string> | null> {
18→  try {
19→    const folder = checkpointFolderPath(checkpointId);
20→    const sessions: Record<string, string> = {};
21→    const count = Math.max(sessionCount, 1);
22→
23→    for (let i = 0; i < count; i++) {
24→      const path = `${folder}/${i}/full.jsonl`;
25→      const content = await fetchFileAtCommit(repoFullName, path, CHECKPOINT_BRANCH, token);
26→      if (content) {
27→        sessions[String(i)] = stripTranscript(content);
28→      }
29→    }
30→
31→    return Object.keys(sessions).length > 0 ? sessions : null;
32→  } catch {
33→    return null;
34→  }
35→}
36→
37→// Fetch and store stripped transcripts for a batch of checkpoints.
38→// Shared by processSessionsPushEvent and processCommitPushEvent.
39→export async function fetchAndStoreTranscripts(
40→  db: Db,
41→  repoId: string,
42→  repoFullName: string,
43→  checkpointIds: string[],
44→  sessionCountMap: Map<string, number | null>,
45→  token: string,
46→): Promise<number> {
47→  const transcriptUpdates: Array<{ checkpoint_id: string; transcript_stripped: string }> = [];
48→  for (let i = 0; i < checkpointIds.length; i += TRANSCRIPT_CONCURRENCY) {
49→    const batch = checkpointIds.slice(i, i + TRANSCRIPT_CONCURRENCY);
50→    const results = await Promise.all(
51→      batch.map((cpId) => fetchAndStripTranscript(repoFullName, cpId, sessionCountMap.get(cpId) ?? 1, token)),
52→    );
53→    for (let j = 0; j < results.length; j++) {
54→      if (results[j]) {
55→        transcriptUpdates.push({
56→          checkpoint_id: batch[j],
57→          transcript_stripped: JSON.stringify(results[j]),
58→        });
59→      }
60→    }
61→  }
62→  if (transcriptUpdates.length > 0) {
63→    await db.checkpoints.updateTranscriptBatch(repoId, transcriptUpdates);
64→  }
65→  return transcriptUpdates.length;
66→}
