  1→// Strips transcript JSONL to only the fields needed by transcript parsers.
  2→// Reduces size by ~60-80% for efficient DB storage.
  3→//
  4→// The parsers read:
  5→// - type, timestamp, requestId, uuid, message.id, message.model, message.content, toolUseResult
  6→// We drop: progress, file-history-snapshot, queue-operation, system entries
  7→// We strip: thinking blocks, tool_use caller field, unnecessary assistant fields
  8→
  9→// Entry types that carry no parser-relevant data
 10→const DROPPED_TYPES = new Set([
 11→  "progress",
 12→  "file-history-snapshot",
 13→  "queue-operation",
 14→  "system",
 15→]);
 16→
 17→/**
 18→ * Strip a JSONL transcript to only the fields the parsers need.
 19→ * Processes line-by-line. Returns stripped JSONL string.
 20→ */
 21→export function stripTranscript(jsonlContent: string): string {
 22→  const lines = jsonlContent.split("\n");
 23→  const result: string[] = [];
 24→
 25→  for (const line of lines) {
 26→    const trimmed = line.trim();
 27→    if (!trimmed) continue;
 28→
 29→    let parsed: Record<string, unknown>;
 30→    try {
 31→      parsed = JSON.parse(trimmed);
 32→    } catch {
 33→      // Skip malformed lines
 34→      continue;
 35→    }
 36→
 37→    const entryType = parsed.type as string | undefined;
 38→
 39→    // Drop entry types that parsers ignore
 40→    if (entryType && DROPPED_TYPES.has(entryType)) {
 41→      continue;
 42→    }
 43→
 44→    const stripped = stripEntry(parsed, entryType);
 45→    if (stripped) {
 46→      result.push(JSON.stringify(stripped));
 47→    }
 48→  }
 49→
 50→  return result.join("\n");
 51→}
