 53→function stripEntry(
 54→  parsed: Record<string, unknown>,
 55→  entryType: string | undefined,
 56→): Record<string, unknown> | null {
 57→  if (entryType === "assistant") {
 58→    return stripAssistantEntry(parsed);
 59→  }
 60→
 61→  if (entryType === "user") {
 62→    return stripUserEntry(parsed);
 63→  }
 64→
 65→  // Unknown entry type — pass through with just type/timestamp/message to be safe
 66→  // This handles future entry types or non-Claude agents
 67→  const out: Record<string, unknown> = {};
 68→  if (parsed.type !== undefined) out.type = parsed.type;
 69→  if (parsed.timestamp !== undefined) out.timestamp = parsed.timestamp;
 70→  if (parsed.message !== undefined) out.message = parsed.message;
 71→  if (parsed.uuid !== undefined) out.uuid = parsed.uuid;
 72→  if (parsed.requestId !== undefined) out.requestId = parsed.requestId;
 73→  return out;
 74→}
 75→
 76→function stripAssistantEntry(
 77→  parsed: Record<string, unknown>,
 78→): Record<string, unknown> {
 79→  const out: Record<string, unknown> = {
 80→    type: "assistant",
 81→  };
 82→
 83→  if (parsed.timestamp !== undefined) out.timestamp = parsed.timestamp;
 84→  if (parsed.requestId !== undefined) out.requestId = parsed.requestId;
 85→
 86→  const message = parsed.message as Record<string, unknown> | undefined;
 87→  if (message) {
 88→    const strippedMessage: Record<string, unknown> = {};
 89→    if (message.id !== undefined) strippedMessage.id = message.id;
 90→    if (message.model !== undefined) strippedMessage.model = message.model;
 91→
 92→    // Strip content: remove thinking blocks, strip caller from tool_use
 93→    if (message.content !== undefined) {
 94→      strippedMessage.content = stripAssistantContent(message.content);
 95→    }
 96→
 97→    out.message = strippedMessage;
 98→  }
 99→
100→  return out;
101→}
102→
103→function stripAssistantContent(content: unknown): unknown {
104→  // String content — keep as-is
105→  if (typeof content === "string") return content;
106→
107→  // Array of content blocks
108→  if (Array.isArray(content)) {
109→    const stripped: unknown[] = [];
110→    for (const block of content) {
111→      if (typeof block !== "object" || block === null) {
112→        stripped.push(block);
113→        continue;
114→      }
115→
116→      const b = block as Record<string, unknown>;
117→
118→      // Drop thinking blocks
119→      if (b.type === "thinking" || b.type === "redacted_thinking") {
120→        continue;
121→      }
122→
123→      // Strip tool_use: keep id, name, input — drop caller
124→      if (b.type === "tool_use") {
125→        const toolUse: Record<string, unknown> = {
126→          type: "tool_use",
127→        };
128→        if (b.id !== undefined) toolUse.id = b.id;
129→        if (b.name !== undefined) toolUse.name = b.name;
130→        if (b.input !== undefined) toolUse.input = b.input;
131→        stripped.push(toolUse);
132→        continue;
133→      }
134→
135→      // Other block types (text, image) — keep as-is
136→      stripped.push(block);
137→    }
138→    return stripped;
139→  }
140→
141→  return content;
142→}
143→
144→function stripUserEntry(
145→  parsed: Record<string, unknown>,
146→): Record<string, unknown> {
147→  const out: Record<string, unknown> = {
148→    type: "user",
149→  };
150→
151→  if (parsed.timestamp !== undefined) out.timestamp = parsed.timestamp;
152→  if (parsed.uuid !== undefined) out.uuid = parsed.uuid;
153→
154→  // Keep toolUseResult but minimize it
155→  if (parsed.toolUseResult !== undefined) {
156→    out.toolUseResult = stripToolUseResult(parsed.toolUseResult);
157→  }
158→
159→  const message = parsed.message as Record<string, unknown> | undefined;
160→  if (message) {
161→    const strippedMessage: Record<string, unknown> = {};
162→
163→    if (message.content !== undefined) {
164→      strippedMessage.content = stripUserContent(message.content);
165→    }
166→
167→    out.message = strippedMessage;
168→  }
169→
170→  return out;
171→}
172→
173→function stripUserContent(content: unknown): unknown {
174→  // String content — keep as-is
175→  if (typeof content === "string") return content;
176→
177→  // Array of content blocks
178→  if (Array.isArray(content)) {
179→    const stripped: unknown[] = [];
180→    for (const block of content) {
181→      if (typeof block !== "object" || block === null) {
182→        stripped.push(block);
183→        continue;
184→      }
185→
186→      const b = block as Record<string, unknown>;
187→
188→      // tool_result: keep type and tool_use_id only (content is in toolUseResult)
189→      if (b.type === "tool_result") {
190→        const toolResult: Record<string, unknown> = {
191→          type: "tool_result",
192→        };
193→        if (b.tool_use_id !== undefined) toolResult.tool_use_id = b.tool_use_id;
194→        stripped.push(toolResult);
195→        continue;
196→      }
197→
198→      // Other block types (text, image) — keep as-is
199→      stripped.push(block);
200→    }
201→    return stripped;
202→  }
203→
204→  return content;
205→}
206→
207→function stripToolUseResult(result: unknown): unknown {
208→  if (typeof result !== "object" || result === null) return result;
209→
210→  const r = result as Record<string, unknown>;
211→  const out: Record<string, unknown> = {};
212→
213→  if (r.type !== undefined) out.type = r.type;
214→  if (r.file !== undefined) out.file = r.file;
215→  if (r.error !== undefined) out.error = r.error;
216→  if (r.answers !== undefined) out.answers = r.answers;
217→
218→  return out;
219→}
