138→
139→  if (checkpointMeta?.sessions && checkpointMeta.sessions.length > 0) {
140→    const sessionPromises = checkpointMeta.sessions.map((sessionPaths, idx) =>
141→      (async (): Promise<SessionTranscript | null> => {
142→        try {
143→          const [transcriptContent, sessionMetadataContent] = await Promise.all([
144→            fetchFileAtCommit(repoFullName, stripLeadingSlash(sessionPaths.transcript), CHECKPOINT_BRANCH, token).catch(() => null),
145→            fetchFileAtCommit(repoFullName, stripLeadingSlash(sessionPaths.metadata), CHECKPOINT_BRANCH, token).catch(() => null),
146→          ]);
