 66→    const content = pendingAssistantParts.join("\n\n").trim();
 67→    if (content || pendingToolCalls.length > 0) {
 68→      result.push({
 69→        id: pendingId ?? crypto.randomUUID(),
 70→        role: "assistant",
 71→        content,
 72→        timestamp: pendingTimestamp ?? new Date().toISOString(),
 73→        toolCalls:
 74→          pendingToolCalls.length > 0 ? [...pendingToolCalls] : undefined,
 75→      });
 76→    }
 77→    pendingAssistantParts = [];
 78→    pendingToolCalls = [];
 79→    pendingTimestamp = null;
 80→    pendingId = null;
 81→  };
 82→
 83→  for (const line of lines) {
 84→    let event: CopilotEvent;
 85→    try {
 86→      event = JSON.parse(line);
 87→    } catch {
 88→      continue;
 89→    }
 90→
 91→    if (!event.type || !event.data) continue;
 92→
 93→    switch (event.type) {
 94→      case "user.message": {
 95→        // Flush any pending assistant content before a new user message
 96→        flushAssistant();
 97→
 98→        const content =
 99→          typeof event.data.content === "string"
100→            ? event.data.content.trim()
101→            : "";
102→        if (content) {
103→          result.push({
104→            id: event.id ?? crypto.randomUUID(),
105→            role: "user",
106→            content,
107→            timestamp: event.timestamp ?? new Date().toISOString(),
108→          });
109→        }
110→        break;
111→      }
112→
113→      case "assistant.message": {
114→        const content =
115→          typeof event.data.content === "string"
116→            ? event.data.content.trim()
117→            : "";
118→        if (content) {
119→          pendingAssistantParts.push(content);
120→        }
121→
122→        // Set timestamp from first assistant.message in this turn
123→        if (!pendingTimestamp) {
124→          pendingTimestamp = event.timestamp ?? new Date().toISOString();
125→        }
126→        if (!pendingId) {
127→          pendingId = event.id;
128→        }
129→
130→        // Extract tool requests
131→        const toolRequests = event.data.toolRequests as
132→          | CopilotToolRequest[]
133→          | undefined;
134→        if (Array.isArray(toolRequests)) {
135→          for (const tr of toolRequests) {
136→            if (tr.name) {
137→              pendingToolCalls.push({
138→                id: tr.toolCallId ?? crypto.randomUUID(),
139→                name: tr.name,
140→                input: tr.arguments ?? {},
141→                timestamp: event.timestamp ?? new Date().toISOString(),
142→              });
143→            }
144→          }
145→        }
146→        break;
147→      }
148→
149→      case "tool.execution_complete": {
150→        // Match tool result back to pending tool call by toolCallId
151→        const toolCallId = event.data.toolCallId as string | undefined;
152→        if (toolCallId) {
153→          const matchingCall = pendingToolCalls.find(
154→            (tc) => tc.id === toolCallId,
155→          );
156→          if (matchingCall) {
157→            const success = event.data.success as boolean | undefined;
158→            const error = event.data.error as
159→              | { message?: string }
160→              | undefined;
161→            const resultData = event.data.result as
162→              | { content?: string }
163→              | undefined;
164→
165→            const toolResult: ToolCallResult = {
166→              type: success === false ? "error" : "text",
167→            };
168→            if (error?.message) {
169→              toolResult.error = error.message;
170→            }
171→            if (resultData?.content) {
172→              toolResult.output = resultData.content;
173→            }
174→            matchingCall.result = toolResult;
175→          }
176→        }
177→        break;
178→      }
179→
180→      case "assistant.turn_end": {
181→        // Flush assistant content at end of turn
182→        flushAssistant();
183→        break;
184→      }
185→
186→      // session.start, session.model_change, assistant.turn_start,
187→      // tool.execution_start are metadata — skip
188→      default:
189→        break;
190→    }
191→  }
192→
193→  // Flush any remaining assistant content (in case no turn_end at EOF)
194→  flushAssistant();
195→
196→  return result;
197→}
