 15→/**
 16→ * Extract plain text from a Cursor message content array.
 17→ */
 18→function extractText(content: unknown): string {
 19→  if (typeof content === "string") return content;
 20→  if (!Array.isArray(content)) return "";
 21→
 22→  const parts: string[] = [];
 23→  for (const block of content) {
 24→    if (typeof block === "object" && block !== null) {
 25→      const b = block as Record<string, unknown>;
 26→      if (b.type === "text" && typeof b.text === "string") {
 27→        parts.push(b.text);
 28→      }
 29→    }
 30→  }
 31→  return parts.join("\n");
 32→}
