describe("GeminiParser parsing", () => {
  it("parses a basic Gemini transcript with user and assistant messages", () => {
    const transcript = JSON.stringify({
      messages: [
        {
          id: "msg-u1",
          timestamp: "2026-02-18T21:27:47.641Z",
          type: "user",
          content: "Modify hello.go to print Hello E2E",
        },
        {
          id: "msg-a1",
          timestamp: "2026-02-18T21:28:06.741Z",
          type: "gemini",
          content: "The hello.go file has been updated.",
        },
      ],
    });

    const parser = getParserForAgent("Gemini CLI");
    const result = parser.parse(transcript);

    expect(result.isFallback).toBe(false);
    expect(result.messages).toHaveLength(2);
    expect(result.messages[0].role).toBe("user");
    expect(result.messages[0].content).toBe("Modify hello.go to print Hello E2E");
    expect(result.messages[0].timestamp).toBe("2026-02-18T21:27:47.641Z");
    expect(result.messages[1].role).toBe("assistant");
    expect(result.messages[1].content).toBe("The hello.go file has been updated.");
    expect(result.messages[1].timestamp).toBe("2026-02-18T21:28:06.741Z");
  });

  it("extracts tool calls from assistant messages", () => {
    const transcript = JSON.stringify({
      messages: [
        {
          id: "msg-u1",
          timestamp: "2026-02-18T21:27:47.641Z",
          type: "user",
          content: "Read hello.go",
        },
        {
          id: "msg-a1",
          timestamp: "2026-02-18T21:27:53.735Z",
          type: "gemini",
          content: "",
          toolCalls: [
            {
              id: "read_file-123",
              name: "read_file",
              args: { file_path: "hello.go" },
            },
          ],
        },
      ],
    });

    const parser = getParserForAgent("Gemini CLI");
    const result = parser.parse(transcript);

    expect(result.messages).toHaveLength(2);
    expect(result.messages[1].role).toBe("assistant");
    expect(result.messages[1].toolCalls).toHaveLength(1);
    expect(result.messages[1].toolCalls![0].name).toBe("read_file");
    expect(result.messages[1].toolCalls![0].input).toEqual({ file_path: "hello.go" });
  });

  it("includes tool-only messages (empty content with toolCalls)", () => {
    const transcript = JSON.stringify({
      messages: [
        {
          id: "msg-u1",
          timestamp: "2026-02-18T21:27:47.641Z",
          type: "user",
          content: "Create a file",
        },
        {
          id: "msg-a1",
          timestamp: "2026-02-18T21:27:53.735Z",
          type: "gemini",
          content: "",
          toolCalls: [
            { id: "tc-1", name: "replace", args: { file_path: "hello.go" } },
          ],
        },
        {
          id: "msg-a2",
          timestamp: "2026-02-18T21:28:06.741Z",
          type: "gemini",
          content: "Done.",
        },
      ],
    });

    const parser = getParserForAgent("Gemini CLI");
    const result = parser.parse(transcript);

    expect(result.messages).toHaveLength(3);
    expect(result.messages[1].toolCalls).toHaveLength(1);
    expect(result.messages[2].content).toBe("Done.");
  });

  it("preserves message IDs from the transcript", () => {
    const transcript = JSON.stringify({
      messages: [
        { id: "custom-id-123", timestamp: "2026-01-01T00:00:00Z", type: "user", content: "Hello" },
      ],
    });

    const parser = getParserForAgent("Gemini CLI");
    const result = parser.parse(transcript);

    expect(result.messages[0].id).toBe("custom-id-123");
  });

  it("returns empty messages for invalid JSON", () => {
