import { describe, it, expect } from "vitest";
import { getParserForAgent } from "./registry";
import { ClaudeCodeParser } from "./claude-code-parser";
import { CopilotCliParser } from "./copilot-cli-parser";
import { CursorParser } from "./cursor-parser";
import { FallbackParser } from "./fallback-parser";
import { GeminiParser } from "./gemini-parser";
import { OpenCodeParser } from "./opencode-parser";

describe("getParserForAgent", () => {
  describe("Claude Code variations", () => {
    it.each([
      "Claude Code",
      "claude code",
      "claude",
      "Claude",
      "CLAUDE",
      "claude-code",
      "CLAUDE CODE",
      "CLAUDE-CODE",
    ])('returns ClaudeCodeParser for "%s"', (agent) => {
      const parser = getParserForAgent(agent);
      expect(parser).toBeInstanceOf(ClaudeCodeParser);
      const result = parser.parse("");
      expect(result.isFallback).toBe(false);
    });

    it("handles leading/trailing whitespace", () => {
      const parser = getParserForAgent("  Claude Code  ");
      expect(parser).toBeInstanceOf(ClaudeCodeParser);
    });
  });

  describe("unknown agents", () => {
    it.each([
      "agent",
      "Agent",
      "NewAI v2",
      "",
    ])('returns FallbackParser for "%s"', (agent) => {
      const parser = getParserForAgent(agent);
      expect(parser).toBeInstanceOf(FallbackParser);
      const result = parser.parse("");
      expect(result.isFallback).toBe(true);
      expect(result.warning).toBeTruthy();
    });
  });

  describe("FallbackParser produces valid output", () => {
    it("parses Claude Code JSONL with isFallback=true", () => {
      const jsonl = [
        JSON.stringify({
          type: "user",
          message: { content: "Hello", id: "u1" },
          timestamp: "2024-01-01T00:00:00Z",
          uuid: "uuid-1",
        }),
        JSON.stringify({
          type: "assistant",
          message: { content: "Hi there", id: "a1" },
          timestamp: "2024-01-01T00:00:01Z",
          requestId: "req-1",
        }),
      ].join("\n");

      const parser = getParserForAgent("unknown-agent");
      const result = parser.parse(jsonl);

      expect(result.isFallback).toBe(true);
      expect(result.warning).toBeTruthy();
      expect(result.messages).toHaveLength(2);
      expect(result.messages[0].role).toBe("user");
      expect(result.messages[1].role).toBe("assistant");
    });
  });

  describe("ClaudeCodeParser strips internal tags", () => {
    it("strips system-reminder, command-message, and command-name tags", () => {
      const jsonl = [
        JSON.stringify({
          type: "user",
          message: { content: "Hello", id: "u1" },
          timestamp: "2024-01-01T00:00:00Z",
          uuid: "uuid-1",
        }),
        JSON.stringify({
          type: "assistant",
          message: {
            content: "Reply <system-reminder>secret</system-reminder> here <command-name>cmd</command-name> end",
            id: "a1",
          },
          timestamp: "2024-01-01T00:00:01Z",
          requestId: "req-1",
        }),
      ].join("\n");

      const parser = getParserForAgent("claude");
      const result = parser.parse(jsonl);

      expect(result.messages[1].content).toBe("Reply  here  end");
    });
  });

  describe("OpenCode variations", () => {
    it.each([
      "OpenCode",
      "opencode",
      "OPENCODE",
      "open code",
      "Open Code",
      "OPEN CODE",
      "open-code",
      "Open-Code",
      "OPEN-CODE",
    ])('returns OpenCodeParser for "%s"', (agent) => {
      const parser = getParserForAgent(agent);
      expect(parser).toBeInstanceOf(OpenCodeParser);
      const result = parser.parse("{}");
      expect(result.isFallback).toBe(false);
    });
  });

  describe("OpenCodeParser parsing", () => {
    it("parses a basic OpenCode session log", () => {
      const log = JSON.stringify({
        info: {
          time: {
            created: 1700000000000,
          },
        },
        messages: [
          {
            info: { role: "user", time: { created: 1700000000000 }, id: "msg-u1" },
            parts: [{ type: "text", text: "Hello" }],
          },
          {
            info: { role: "assistant", time: { created: 1700000001000, completed: 1700000002000 }, id: "msg-a1" },
            parts: [
              { type: "step-start", snapshot: "abc123" },
              {
                type: "tool",
                tool: "read",
                state: {
                  input: { path: "/tmp/file.txt" },
                  output: "file contents here",
                  status: "completed",
                  time: { start: 1700000001500, end: 1700000001600 },
                },
              },
              { type: "text", text: "Here is the file content." },
              { type: "step-finish", reason: "stop" },
            ],
          },
        ],
      });

      const parser = getParserForAgent("opencode");
      const result = parser.parse(log);

      expect(result.isFallback).toBe(false);
      expect(result.messages).toHaveLength(2);

      expect(result.messages[0].role).toBe("user");
      expect(result.messages[0].content).toBe("Hello");

      expect(result.messages[1].role).toBe("assistant");
      expect(result.messages[1].content).toBe("Here is the file content.");
      expect(result.messages[1].toolCalls).toHaveLength(1);
      expect(result.messages[1].toolCalls![0].name).toBe("read");
      expect(result.messages[1].toolCalls![0].input).toEqual({
        path: "/tmp/file.txt",
      });
      expect(result.messages[1].toolCalls![0].result).toEqual({
        type: "text",
        output: "file contents here",
      });
    });

    it("groups consecutive assistant messages into one turn", () => {
      const log = JSON.stringify({
        info: { time: { created: 1700000000000 } },
        messages: [
          {
            info: { role: "user", time: { created: 1700000000000 } },
            parts: [{ type: "text", text: "Fix the bug" }],
          },
          {
            info: { role: "assistant", time: { created: 1700000001000 }, id: "msg-a1" },
            parts: [
              { type: "tool", tool: "read", state: { input: { path: "a.ts" }, output: "code", status: "completed" } },
            ],
          },
          {
            info: { role: "assistant", time: { created: 1700000002000 }, id: "msg-a2" },
            parts: [
              { type: "tool", tool: "edit", state: { input: { path: "a.ts" }, output: "ok", status: "completed" } },
              { type: "text", text: "Fixed it." },
            ],
          },
        ],
      });

      const parser = getParserForAgent("opencode");
      const result = parser.parse(log);

      expect(result.messages).toHaveLength(2);
      expect(result.messages[1].role).toBe("assistant");
      expect(result.messages[1].content).toBe("Fixed it.");
      expect(result.messages[1].toolCalls).toHaveLength(2);
      expect(result.messages[1].toolCalls![0].name).toBe("read");
      expect(result.messages[1].toolCalls![1].name).toBe("edit");
    });

    it("handles tool errors", () => {
      const log = JSON.stringify({
        info: { time: { created: 1700000000000 } },
        messages: [
          {
            info: { role: "user", time: { created: 1700000000000 } },
            parts: [{ type: "text", text: "Read file" }],
          },
          {
            info: { role: "assistant", time: { created: 1700000001000 } },
            parts: [
              {
                type: "tool",
                tool: "read",
                state: { input: { path: "missing.txt" }, output: "file not found", status: "error" },
              },
              { type: "text", text: "The file was not found." },
            ],
          },
        ],
      });

      const parser = getParserForAgent("opencode");
      const result = parser.parse(log);

      expect(result.messages[1].toolCalls![0].result).toEqual({
        type: "error",
        output: "file not found",
        error: "file not found",
      });
    });

    it("returns empty messages for invalid JSON", () => {
      const parser = getParserForAgent("opencode");
      const result = parser.parse("not json");

      expect(result.isFallback).toBe(false);
      expect(result.messages).toHaveLength(0);
    });

    it("converts epoch ms timestamp to ISO string", () => {
      const log = JSON.stringify({
        info: { time: { created: 1700000000000 } },
        messages: [
          {
            info: { role: "user", time: { created: 1700000000000 } },
            parts: [{ type: "text", text: "Hi" }],
          },
        ],
      });

      const parser = getParserForAgent("opencode");
      const result = parser.parse(log);

      expect(result.messages[0].timestamp).toBe(
        new Date(1700000000000).toISOString(),
      );
    });

    it("uses per-message timestamps", () => {
      const log = JSON.stringify({
        info: { time: { created: 1700000000000 } },
        messages: [
          {
            info: { role: "user", time: { created: 1700000010000 } },
            parts: [{ type: "text", text: "Hello" }],
          },
          {
            info: { role: "assistant", time: { created: 1700000020000, completed: 1700000030000 } },
            parts: [{ type: "text", text: "Hi there" }],
          },
        ],
      });

      const parser = getParserForAgent("opencode");
      const result = parser.parse(log);

      expect(result.messages[0].timestamp).toBe(new Date(1700000010000).toISOString());
      expect(result.messages[1].timestamp).toBe(new Date(1700000020000).toISOString());
    });
  });

  describe("Factory AI Droid variations", () => {
    it.each([
      "Factory AI Droid",
      "factory ai droid",
      "FACTORY AI DROID",
      "factoryai-droid",
      "droid",
      "Droid",
      "DROID",
    ])('returns ClaudeCodeParser for "%s"', (agent) => {
      const parser = getParserForAgent(agent);
      expect(parser).toBeInstanceOf(ClaudeCodeParser);
      const result = parser.parse("");
      expect(result.isFallback).toBe(false);
    });
  });

  describe("Cursor variations", () => {
    it.each([
      "Cursor",
      "cursor",
      "CURSOR",
    ])('returns CursorParser for "%s"', (agent) => {
      const parser = getParserForAgent(agent);
      expect(parser).toBeInstanceOf(CursorParser);
      const result = parser.parse("");
      expect(result.isFallback).toBe(false);
    });
  });

  describe("CursorParser parsing", () => {
    it("parses a basic Cursor transcript", () => {
      const jsonl = [
        JSON.stringify({
          role: "user",
          message: { content: [{ type: "text", text: "<user_query>\nHello world\n</user_query>" }] },
        }),
        JSON.stringify({
          role: "assistant",
          message: { content: [{ type: "text", text: "Hi there!" }] },
        }),
      ].join("\n");

