import type { TranscriptMessage, ToolCall } from "../../types";
import type { TranscriptParser, TranscriptParseResult } from "./types";

interface GeminiRawMessage {
  id?: string;
  type?: string;
  content?: unknown;
  timestamp?: string;
  toolCalls?: Array<{
    id: string;
    name: string;
    args?: Record<string, unknown>;
  }>;
}

interface GeminiLog {
  messages?: GeminiRawMessage[];
}

/**
 * Extract text from Gemini message content.
 * Handles both string content and array-of-parts format:
 *   - string: "response text"
 *   - array:  [{"text": "prompt text"}, ...]
 */
function extractTextContent(content: unknown): string {
  if (typeof content === "string") return content;
  if (!Array.isArray(content)) return "";

  const texts: string[] = [];
  for (const part of content) {
    if (typeof part === "object" && part !== null) {
      const p = part as Record<string, unknown>;
      if (typeof p.text === "string" && p.text) {
        texts.push(p.text);
      }
    }
  }
  return texts.join("\n");
}

function extractToolCalls(
  msg: GeminiRawMessage,
  timestamp: string,
): ToolCall[] | undefined {
  if (!msg.toolCalls || msg.toolCalls.length === 0) return undefined;

  return msg.toolCalls.map((tc) => ({
    id: tc.id,
    name: tc.name,
    input: (tc.args ?? {}) as Record<string, unknown>,
    timestamp,
  }));
}

/**
 * Parse a Gemini CLI transcript into TranscriptMessage[].
 * Format: single JSON object with a `messages` array.
 * User messages have type "user", assistant messages have type "gemini".
 */
function parseGeminiTranscript(jsonContent: string): TranscriptMessage[] {
  let log: GeminiLog;
  try {
    log = JSON.parse(jsonContent);
  } catch {
    return [];
  }

  if (!Array.isArray(log.messages)) return [];

  const messages: TranscriptMessage[] = [];

  for (const msg of log.messages) {
    if (msg.type !== "user" && msg.type !== "gemini") continue;

    const role: "user" | "assistant" =
      msg.type === "user" ? "user" : "assistant";
    const timestamp = msg.timestamp || new Date().toISOString();

    messages.push({
      id: msg.id || crypto.randomUUID(),
      role,
      content: extractTextContent(msg.content),
      timestamp,
      toolCalls:
        role === "assistant" ? extractToolCalls(msg, timestamp) : undefined,
    });
  }

  return messages;
}

/**
 * Parser for Gemini CLI transcripts.
 */
export class GeminiParser implements TranscriptParser {
  readonly name = "Gemini CLI";

  parse(jsonContent: string): TranscriptParseResult {
    const messages = parseGeminiTranscript(jsonContent);

    return {
      messages,
      isFallback: false,
    };
  }
}

