432→func TestNormalizeGeminiTranscript(t *testing.T) {
433→	t.Parallel()
434→
435→	// Raw Gemini format has content as array of objects for user messages
436→	raw := []byte(`{"messages":[{"type":"user","content":[{"text":"fix the bug"}]},{"type":"gemini","content":"ok"}]}`)
437→	normalized, err := normalizeGeminiTranscript(raw)
438→	if err != nil {
439→		t.Fatalf("normalizeGeminiTranscript() error: %v", err)
440→	}
441→
442→	// After normalization, content should be a plain string
443→	var result struct {
444→		Messages []struct {
445→			Type    string `json:"type"`
446→			Content string `json:"content"`
447→		} `json:"messages"`
448→	}
449→	if err := json.Unmarshal(normalized, &result); err != nil {
450→		t.Fatalf("failed to parse normalized transcript: %v", err)
451→	}
