700→// buildTreeWithChanges builds a git tree with the given changes.
701→// metadataDir is the relative path for git tree entries, metadataDirAbs is the absolute path
702→// for filesystem operations (needed when CLI is run from a subdirectory).
703→//
704→// Uses ApplyTreeChanges (tree surgery) instead of FlattenTree+BuildTreeFromEntries,
705→// so only affected subtrees are read/rebuilt — O(changed dirs) instead of O(total files).
706→func (s *GitStore) buildTreeWithChanges(
707→	ctx context.Context,
708→	baseTreeHash plumbing.Hash,
709→	modifiedFiles, deletedFiles []string,
710→	metadataDir, metadataDirAbs string,
711→) (plumbing.Hash, error) {
712→	// Get worktree root for resolving file paths
713→	// This is critical because fileExists() and createBlobFromFile() use os.Stat()
714→	// which resolves relative to CWD. The modifiedFiles are repo-relative paths,
715→	// so we must resolve them against repo root, not CWD.
716→	repoRoot, err := paths.WorktreeRoot(ctx)
717→	if err != nil {
718→		return plumbing.ZeroHash, fmt.Errorf("failed to get worktree root: %w", err)
719→	}
720→
721→	// Build list of tree changes
722→	changes := make([]TreeChange, 0, len(modifiedFiles)+len(deletedFiles))
723→
724→	// Deleted files → nil Entry means deletion
725→	for _, file := range deletedFiles {
726→		changes = append(changes, TreeChange{Path: file, Entry: nil})
727→	}
728→
729→	// Modified/new files → create blobs from disk
730→	for _, file := range modifiedFiles {
731→		absPath := filepath.Join(repoRoot, file)
732→		if !fileExists(absPath) {
733→			// File disappeared since detection — treat as deletion
734→			changes = append(changes, TreeChange{Path: file, Entry: nil})
735→			continue
736→		}
737→
738→		blobHash, mode, blobErr := createBlobFromFile(s.repo, absPath)
739→		if blobErr != nil {
740→			// Skip files that can't be staged (may have been deleted since detection)
741→			continue
742→		}
743→
744→		changes = append(changes, TreeChange{
745→			Path: file,
746→			Entry: &object.TreeEntry{
747→				Mode: mode,
748→				Hash: blobHash,
749→			},
750→		})
751→	}
752→
753→	// Metadata directory files
754→	if metadataDir != "" && metadataDirAbs != "" {
755→		metaChanges, metaErr := addDirectoryToChanges(s.repo, metadataDirAbs, metadataDir)
756→		if metaErr != nil {
757→			return plumbing.ZeroHash, fmt.Errorf("failed to add metadata directory: %w", metaErr)
758→		}
759→		changes = append(changes, metaChanges...)
760→	}
761→
762→	return ApplyTreeChanges(s.repo, baseTreeHash, changes)
763→}
