807→// createBlobFromFile creates a blob object from a file in the working directory.
808→func createBlobFromFile(repo *git.Repository, filePath string) (plumbing.Hash, filemode.FileMode, error) {
809→	info, err := os.Stat(filePath)
810→	if err != nil {
811→		return plumbing.ZeroHash, 0, fmt.Errorf("failed to stat file: %w", err)
812→	}
813→
814→	// Determine file mode
815→	mode := filemode.Regular
816→	if info.Mode()&0o111 != 0 {
817→		mode = filemode.Executable
818→	}
819→	if info.Mode()&os.ModeSymlink != 0 {
820→		mode = filemode.Symlink
821→	}
822→
823→	// Read file contents
824→	content, err := os.ReadFile(filePath) //nolint:gosec // filePath comes from walking the repository
825→	if err != nil {
826→		return plumbing.ZeroHash, 0, fmt.Errorf("failed to read file: %w", err)
827→	}
828→
829→	// Create blob object
830→	obj := repo.Storer.NewEncodedObject()
831→	obj.SetType(plumbing.BlobObject)
832→	obj.SetSize(int64(len(content)))
833→
834→	writer, err := obj.Writer()
835→	if err != nil {
836→		return plumbing.ZeroHash, 0, fmt.Errorf("failed to get object writer: %w", err)
837→	}
838→
839→	_, err = writer.Write(content)
840→	if err != nil {
841→		_ = writer.Close()
842→		return plumbing.ZeroHash, 0, fmt.Errorf("failed to write blob content: %w", err)
843→	}
844→	if err := writer.Close(); err != nil {
845→		return plumbing.ZeroHash, 0, fmt.Errorf("failed to close blob writer: %w", err)
846→	}
847→
848→	hash, err := repo.Storer.SetEncodedObject(obj)
849→	if err != nil {
850→		return plumbing.ZeroHash, 0, fmt.Errorf("failed to store blob object: %w", err)
851→	}
852→
853→	return hash, mode, nil
854→}
