1417→// JSONL files get JSONL-aware redaction; all other files get plain string redaction.
1418→func createRedactedBlobFromFile(repo *git.Repository, filePath, treePath string) (plumbing.Hash, filemode.FileMode, error) {
1419→	info, err := os.Stat(filePath)
1420→	if err != nil {
1421→		return plumbing.ZeroHash, 0, fmt.Errorf("failed to stat file: %w", err)
1422→	}
1423→
1424→	mode := filemode.Regular
1425→	if info.Mode()&0o111 != 0 {
1426→		mode = filemode.Executable
1427→	}
1428→
1429→	content, err := os.ReadFile(filePath) //nolint:gosec // filePath comes from walking the metadata directory
1430→	if err != nil {
1431→		return plumbing.ZeroHash, 0, fmt.Errorf("failed to read file: %w", err)
1432→	}
1433→
1434→	// Skip redaction for binary files — they can't contain text secrets and
1435→	// running string replacement on them would corrupt the data.
1436→	isBin, binErr := binary.IsBinary(bytes.NewReader(content))
1437→	if binErr != nil || isBin {
1438→		hash, err := CreateBlobFromContent(repo, content)
1439→		if err != nil {
1440→			return plumbing.ZeroHash, 0, fmt.Errorf("failed to create blob: %w", err)
1441→		}
1442→		return hash, mode, nil
1443→	}
1444→
1445→	if strings.HasSuffix(treePath, ".jsonl") {
1446→		redacted, jsonlErr := redact.JSONLBytes(content)
1447→		if jsonlErr != nil {
1448→			redacted = redact.Bytes(content)
1449→		}
1450→		content = redacted
1451→	} else {
1452→		content = redact.Bytes(content)
1453→	}
1454→
1455→	hash, err := CreateBlobFromContent(repo, content)
1456→	if err != nil {
1457→		return plumbing.ZeroHash, 0, fmt.Errorf("failed to create blob: %w", err)
1458→	}
1459→	return hash, mode, nil
1460→}
