1462→// GetGitAuthorFromRepo retrieves the git user.name and user.email,
1463→// checking both the repository-local config and the global ~/.gitconfig.
1464→func GetGitAuthorFromRepo(repo *git.Repository) (name, email string) {
1465→	// Get repository config (includes local settings)
1466→	cfg, err := repo.Config()
1467→	if err == nil {
1468→		name = cfg.User.Name
1469→		email = cfg.User.Email
1470→	}
1471→
1472→	// If not found in local config, try global config
1473→	if name == "" || email == "" {
1474→		globalCfg, err := config.LoadConfig(config.GlobalScope)
1475→		if err == nil {
1476→			if name == "" {
1477→				name = globalCfg.User.Name
1478→			}
1479→			if email == "" {
1480→				email = globalCfg.User.Email
1481→			}
1482→		}
1483→	}
1484→
1485→	// Provide sensible defaults if git user is not configured
1486→	if name == "" {
1487→		name = "Unknown"
1488→	}
1489→	if email == "" {
1490→		email = "unknown@local"
1491→	}
1492→
1493→	return name, email
1494→}
